// T[i][v] = P( S(v) << (i*4) )
static uint64_t T[16][16];

static inline uint64_t rl1(uint64_t v){ return (v<<1)|(v>>15); }

static inline uint64_t enc(uint64_t pt, uint64_t k){
    uint64_t st = pt;
    for(int r=0;r<31;r++){
        uint64_t rk = (k>>16);
        st ^= rk;
        // S+P via tables
        uint64_t ns = T[0][st&0xF]^T[1][(st>>4)&0xF]^T[2][(st>>8)&0xF]^T[3][(st>>12)&0xF]
                   ^T[4][(st>>16)&0xF]^T[5][(st>>20)&0xF]^T[6][(st>>24)&0xF]^T[7][(st>>28)&0xF]
                   ^T[8][(st>>32)&0xF]^T[9][(st>>36)&0xF]^T[10][(st>>40)&0xF]^T[11][(st>>44)&0xF]
                   ^T[12][(st>>48)&0xF]^T[13][(st>>52)&0xF]^T[14][(st>>56)&0xF]^T[15][(st>>60)&0xF];
        st = ns;
        k = rl1(k);
    }
    st ^= (k>>16);
    return st;
}

int main(int argc, char**argv){
    uint8_t pb[64]={0,16,32,48,1,17,33,49,2,18,34,50,3,19,35,51,4,20,36,52,5,21,37,53,6,22,38,54,7,23,39,55,8,24,40,56,9,25,41,57,10,26,42,58,11,27,43,59,12,28,44,60,13,29,45,61,14,30,46,62,15,31,47,63};
    memcpy(pbox,pb,64);
    for(int i=0;i<16;i++) for(int v=0;v<16;v++){
        uint64_t s = (uint64_t)sbox[v]<<(i*4);
        uint64_t r=0;
        for(int b=0;b<64;b++) if((s>>b)&1) r|=(1ULL<<pbox[b]);
        T[i][v]=r;
    }
    // sanity: compare with plain impl for test vector
    uint64_t t = enc(0x0000000000000001ULL, REDACTED00000000000000000242ULL);
    printf("selftest: %016llx (expect d684313eb8ceecb8)\n", (unsigned long long)t);
    if(t != 0xd684313eb8ceecb8ULL){ printf("SELFTEST FAIL\n"); return 1; }
    if(argc<4){ printf("usage: %s pt_hex ct_hex nbits [start]\n", argv[0]); return 1; }
    uint64_t pt = strtoull(argv[1],0,16);
    uint64_t ct = strtoull(argv[2],0,16);
    int nbits = atoi(argv[3]);
    uint64_t start = (argc>4)?strtoull(argv[4],0,16):0;
    uint64_t total = (nbits>=64)?~0ULL:(((nbits==64)?~0ULL:((1ULL<<nbits)-1)));
    // benchmark: time 2M encryptions single thread
    // brute force [start, start+total]
    volatile uint64_t found = (uint64_t)-1;
    int done=0;
    #pragma omp parallel for schedule(static) shared(found,done)
    for(uint64_t k=start;k<start+total;k++){
        if(done) continue;
        if(enc(pt,k)==ct){
            #pragma omp critical
            { if(!done){ found=k; done=1; printf("FOUND %016llx\n",(unsigned long long)k); fflush(stdout);} }
        }
    }
    if(!done) printf("NOTFOUND in [%llx,%llx)\n",(unsigned long long)start,(unsigned long long)(start+total));
    return 0;
}
