# Synthesize compact bitsliced circuit for PRESENT S-box via greedy + verify
S=[0xC,0x5,0x6,0xB,0x9,0x0,0xA,0xD,0x3,0xE,0xF,0x8,0x4,0x7,0x1,0x2]
# truth tables as 16-bit masks: bit v = output bit; inputs x0=LSB..x3=MSB of v
def tm(outbit):
    m=0
    for v in range(16):
        if (S[v]>>outbit)&1: m|=1<<v
    return m
T=[tm(i) for i in range(4)]
print(['%04x'%t for t in T])
# Express each output as ANF via Mobius over subsets of {x0..x3}
# var masks: x0 bit v = (v>>0)&1 -> mask where bit v set if v odd, etc.
X=[0]*4
for i in range(4):
    m=0
    for v in range(16):
        if (v>>i)&1: m|=1<<v
    X[i]=m
print('X:',['%04x'%x for x in X])
# ANF: for each output mask T, find coeffs c[S] for S subset of {0..3} with T = XOR_S c[S]*(AND_{i in S} xi)
# Mobius inversion on subset lattice (16 subsets)
def anf(mask):
    # a[S] = AND_{i in S} xi as 16-bit truth mask
    A={}
    for s in range(16):
        m=0xFFFF
        for i in range(4):
            if (s>>i)&1: m&=X[i]
        A[s]=m
    # solve: mask = XOR_{s} c[s]*A[s] via brute force over c (2^16)
    for c in range(1<<16):
        m=0
        for s in range(16):
            if (c>>s)&1:
                # XOR of A[s] replicated? No: c[s] is 0/1 scalar, term = A[s] if c else 0
                m^=A[s]
        if m==mask:
            return c
    return None
for i in range(4):
    c=anf(T[i])
    terms=[s for s in range(16) if (c>>s)&1]
    print('y%d terms:'%i, ['%s'%format(s,'04b') for s in terms], 'count', len(terms))
